  const lines = Array.from({ length: 30 }, (_, i) => "voice-run-full-r32:   1%| " + (200 + i) + "/24192 [04:28<8:56:50, 1.34s/it, lr: 5.0e-05 loss: 2.893e+00]").join("\\n");
