  for (let i = 0; i < 2049; i++) dv.setFloat32(8 + hb.length + F * B + 4 * i, -60, true);
  [-40, -30, -20, -25, -35, -50].forEach((v, i) => dv.setFloat32(8 + hb.length + F * B + 4 * 2049 + 4 * i, v, true));
