  const was = { abc: $("abc").value, cot: document.querySelector('input[name="cot"]:checked').value, want: localStorage.getItem("yue2.wantKey"), lyrics: $("lyrics").value, style: $("style").value, ask: localStorage.getItem("yue2.askScore") };
