  await wait(100);
  HeresyConsole.select("lead_vocal", "mixer"); await wait(80);
  await clk('[data-act="addvca"]'); await wait(100);
  const st = HeresyConsole.state(), G = () => HeresyMixer.k.groups()[0] || {};
