  o.names = [...tree.querySelectorAll('.dv-node .dv-name')].filter((n) => /Before and after|Matched/.test(n.textContent)).map((n) => (n.getAttribute("translate") === "no" ? "!" : "") + n.textContent.replace(/^↳\s*/, "").trim()).join("|");
